"use strict";

// Maths text as it arrives after JSON.parse (single backslashes), grouped by
// NSW Stage 3–5 topic: the notation the prompt asks for plus the off-rule forms
// models produce anyway. Built for RES-31; resourceMathCorpus.test.js renders
// every line and fails on leaked LaTeX, lost dollar signs or fallback warnings.
const C = [];
const add = (topic, ...lines) => lines.forEach((l) => C.push([topic, l]));

